<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'; import { ArrowLeft, RefreshCw } from 'lucide-vue-next'; import { useRouter } from 'vue-router'; import AppLogo from '@/components/AppLogo.vue'; import { api } from '@/services/api'; import { errorMessage } from '@/services/http'; import { useAuthStore } from '@/stores/auth'
const router=useRouter(); const auth=useAuthStore(); const form=reactive({username:'',phone:'',password:'',confirm:'',captchaCode:''}); const captcha=ref({id:'',image:''}); const error=ref(''); const loading=ref(false)
async function refresh(){const value=await api.captcha('REGISTER'); captcha.value={id:value.captchaId,image:value.imageBase64}}
async function submit(){if(form.password!==form.confirm){error.value='两次输入的密码不一致';return} error.value='';loading.value=true;try{await auth.register({...form,captchaId:captcha.value.id});router.push({path:'/login',query:{role:'USER',registered:'1'}})}catch(e){error.value=errorMessage(e);await refresh()}finally{loading.value=false}}
onMounted(refresh)
</script>
<template><main class="auth-page"><section class="auth-aside register-aside"><AppLogo/><div><p class="eyebrow">CREATE ACCOUNT</p><h1>加入铁路通，轻松管理每一次出行</h1><p>注册后可保存乘车人、管理订单，并及时接收行程消息。</p></div></section><section class="auth-panel"><div class="auth-form"><RouterLink to="/login?role=USER" class="back"><ArrowLeft/>返回登录</RouterLink><h2>创建用户账号</h2><form @submit.prevent="submit"><label>用户名<input v-model.trim="form.username" required minlength="4" maxlength="64" pattern="[A-Za-z0-9_]+" placeholder="4–64 位字母、数字或下划线"></label><label>手机号<input v-model.trim="form.phone" pattern="1[3-9][0-9]{9}" placeholder="选填，11 位手机号"></label><div class="form-grid"><label>密码<input v-model="form.password" type="password" required minlength="8" maxlength="64"></label><label>确认密码<input v-model="form.confirm" type="password" required minlength="8" maxlength="64"></label></div><label>验证码<div class="captcha-row"><input v-model.trim="form.captchaCode" required minlength="4" maxlength="4"><button type="button" class="captcha-image" @click="refresh"><img v-if="captcha.image" :src="captcha.image"><RefreshCw/></button></div></label><p v-if="error" class="form-error">{{error}}</p><button class="btn primary wide" :disabled="loading">{{loading?'正在注册…':'完成注册'}}</button></form></div></section></main></template>
